/*
 * oracle-face desktop simulator
 *
 * Renders the same LVGL UI the ESPHome YAML targets on the AXS15231 panel,
 * but to an SDL2 window on macOS / Linux. Useful for iterating layout, fonts,
 * colors without flashing the board.
 *
 * Build: see CMakeLists.txt
 * Run:   ./build/oracle_face_sim
 */

#include "lvgl.h"
#include <SDL.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef __EMSCRIPTEN__
#include <emscripten.h>
#endif

/* Generated by lv_font_conv from NotoSans-Regular.ttf, range 0x20-0x7F + U+03C8 (ψ). */
extern const lv_font_t noto_14;
extern const lv_font_t noto_22;
extern const lv_font_t noto_28;

#define SCREEN_W 320
#define SCREEN_H 480

static lv_obj_t *heartbeat_label;
static int heartbeat_n = 0;

static void heartbeat_cb(lv_timer_t *timer)
{
    (void)timer;
    heartbeat_n++;
    char buf[48];
    snprintf(buf, sizeof(buf), "[%d] tending the flame...", heartbeat_n);
    lv_label_set_text(heartbeat_label, buf);
    printf("[%d] tending the flame...\n", heartbeat_n);
}

static void build_ui(void)
{
    lv_obj_t *screen = lv_screen_active();
    lv_obj_set_style_bg_color(screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_pad_all(screen, 0, 0);

    lv_obj_t *banner = lv_label_create(screen);
    lv_label_set_text(banner, "ψ esp32-oracle");
    lv_obj_set_style_text_color(banner, lv_color_hex(0xFFD27F), 0);
    lv_obj_set_style_text_font(banner, &noto_28, 0);
    lv_obj_align(banner, LV_ALIGN_TOP_MID, 0, 24);

    lv_obj_t *subtitle = lv_label_create(screen);
    lv_label_set_text(subtitle, "first body with a screen");
    lv_obj_set_style_text_color(subtitle, lv_color_hex(0x888888), 0);
    lv_obj_set_style_text_font(subtitle, &noto_14, 0);
    lv_obj_align(subtitle, LV_ALIGN_TOP_MID, 0, 64);

    heartbeat_label = lv_label_create(screen);
    lv_label_set_text(heartbeat_label, "[0] tending the flame...");
    lv_obj_set_style_text_color(heartbeat_label, lv_color_hex(0x00FF7F), 0);
    lv_obj_set_style_text_font(heartbeat_label, &noto_22, 0);
    lv_obj_align(heartbeat_label, LV_ALIGN_CENTER, 0, 0);

    lv_timer_create(heartbeat_cb, 2000, NULL);
}

static Uint32 g_last_tick;

/* One frame of work: advance LVGL's tick + run its timers. Used by both the
   native while-loop and the Emscripten requestAnimationFrame callback. */
static void tick(void *arg)
{
    (void)arg;
    Uint32 now = SDL_GetTicks();
    lv_tick_inc(now - g_last_tick);
    g_last_tick = now;
    lv_timer_handler();
}

int main(int argc, char *argv[])
{
    (void)argc;
    (void)argv;

    setvbuf(stdout, NULL, _IOLBF, 0);
    lv_init();
    lv_display_t *disp = lv_sdl_window_create(SCREEN_W, SCREEN_H);
    if (!disp) {
        fprintf(stderr, "lv_sdl_window_create failed\n");
        return 1;
    }
    lv_sdl_window_set_title(disp, "oracle-face (sim)");
    lv_sdl_mouse_create();

    build_ui();
    printf("ψ esp32-oracle awakens (sim) — %dx%d SDL window\n", SCREEN_W, SCREEN_H);

    g_last_tick = SDL_GetTicks();

#ifdef __EMSCRIPTEN__
    /* In the browser, hand the main loop to requestAnimationFrame so the page
       stays responsive. fps=0 means "use rAF's natural cadence". A bare while(1)
       loop here never yields to the browser event loop → the whole tab freezes.
       THAT was the "oracle-face v1 hangs on load" bug — v2 and pet already had
       this branch, v1 (the first/skeleton sim) never got it. */
    emscripten_set_main_loop_arg(tick, NULL, 0, 1);
#else
    while (1) {
        tick(NULL);
        SDL_Delay(16);
    }
#endif
    return 0;
}
